 private final org.springframework.beans.factory.ObjectProvider<com.hs.jxc.ap.api.CostPayableBasisApi> payableBasis;private final DocumentNumberService numbers;private final JdbcTemplate j; private final AuthorizationService auth; private final FieldPolicyService fields;
