 @Override public Map<String,Object> accountingFact(Access a,String eventType,String type,long id,int seq,LocalDate date,Map<String,Object>frozen){Map<String,Object>source;Map<String,Object>payload=new LinkedHashMap<>();if(type.equals("CST_INBOUND_COST")){source=inbound(a,id,false);var rs=j.queryForList("SELECT base_purchase_amount FROM cst_cost_confirmation WHERE country_id=? AND cost_id=?",a.requireCountry(),id);BigDecimal amount=rs.isEmpty()?null:(BigDecimal)rs.getFirst().get("base_purchase_amount");payload.put("amount",amount);payload.put("costMissing",amount==null);payload.put("rateMissing",amount==null&&"PENDING_RATE".equals(source.get("status")));payload.put("counterpart","PAYABLE");if(source.get("poId")!=null){var identity=purchaseReferences.getObject().financialOrderReference(a,n(source,"bookId"),n(source,"poId"));payload.put("partnerId",identity.get("supplierId"));payload.put("supplierId",identity.get("supplierId"));}if(source.get("poId")==null){payload.put("valuationAmount",amount);payload.put("amount",amount==null?null:ZERO);payload.put("apAmount",amount==null?null:ZERO);payload.put("differenceAmount",amount==null?null:ZERO);payload.put("counterpart","NONE");payload.put("accountingImpact","SOURCE_CONFIRMATION");}}else if(type.equals("CST_ADJUSTMENT")){source=adjustment(a,id,false);payload.put("valuationAmount",source.get("amount"));payload.put("amount",source.get("sourceType").equals("MANUAL")?source.get("amount"):source.get("soldAmount"));payload.put("inventoryAmount",source.get("inventoryAmount"));payload.put("soldAmount",source.get("soldAmount"));payload.put("costMissing",!"CONFIRMED".equals(source.get("status")));payload.put("counterpart",source.get("sourceType").equals("MANUAL")?"MANUAL":"INVENTORY");if(!source.get("sourceType").equals("MANUAL")&&source.get("soldAmount")!=null&&d(source,"soldAmount").signum()==0)payload.put("accountingImpact","SOURCE_CONFIRMATION");}else if(type.equals("CST_EXPENSE")){source=expense(a,id);payload.put("amount",source.get("baseAmount"));payload.put("counterpart","PAYABLE");}else throw ApiException.notFound();postingCost(a,type,id,source,payload);for(String field:List.of("productId","warehouseId","batchId","expenseItemId","baseCurrency"))if(source.get(field)!=null)payload.put(field,source.get(field));return Map.of("bookId",source.get("bookId"),"sourceNo",String.valueOf(source.getOrDefault("docNo",type+"-"+id)),"payload",payload);}
 private void postingCost(Access a,String type,long id,Map<String,Object> source,Map<String,Object> payload){
  if(type.equals("CST_EXPENSE")||type.equals("CST_INBOUND_COST")&&source.get("poId")==null)return;
  if(type.equals("CST_ADJUSTMENT")&&source.get("sourceType").equals("MANUAL")&&"COGS".equals(source.get("target"))){
   BigDecimal raw=(BigDecimal)source.get("amount");
   BigDecimal posting=raw==null?null:AccountingAmounts.split(raw,List.of(raw),ledger.baseScale(a,n(source,"bookId"))).getFirst();
   payload.put("originalCostAmount",raw);payload.put("amount",posting);
   payload.put("postingInventoryAmount",ZERO);payload.put("postingCogsAmount",posting);payload.put("postingCounterpartAmount",posting);
   if(posting!=null&&posting.signum()==0&&!Boolean.TRUE.equals(payload.get("costMissing")))payload.put("accountingImpact","SOURCE_CONFIRMATION");
   return;
  }
  var value=costAmounts.delta(a.requireCountry(),n(source,"bookId"),type,id,ledger.baseScale(a,n(source,"bookId")));
  payload.put("originalCostAmount",payload.get("amount"));payload.put("costMissing",value.amount()==null);
  if(type.equals("CST_INBOUND_COST")){var basis=payableBasis.getObject().principal(a,id);payload.put("payableBasis",basis);payload.put("payableBasisMissing",!Boolean.TRUE.equals(basis.get("ready")));payload.put("payableBasisReason",basis.get("reason"));BigDecimal ap=(BigDecimal)basis.get("principalAmount");payload.put("apAmount",ap);payload.put("differenceAmount",ap==null||value.amount()==null?null:ap.subtract(value.amount()));payload.put("payableRecognition",true);}
  BigDecimal amount=value.amount();if(type.equals("CST_ADJUSTMENT")&&!source.get("sourceType").equals("MANUAL"))amount=amount==null?null:amount.negate();
  payload.put("amount",amount);if(type.equals("CST_ADJUSTMENT")&&source.get("sourceType").equals("MANUAL"))payload.put("inventoryAmount",amount);if(type.equals("CST_ADJUSTMENT")&&!source.get("sourceType").equals("MANUAL"))payload.put("soldAmount",amount);
  if(type.equals("CST_ADJUSTMENT")){
   boolean manual=source.get("sourceType").equals("MANUAL");
   // One existing inventory precision delta supplies both sides of a reclassification.
   payload.put("postingInventoryAmount",value.amount());
   payload.put("postingCogsAmount",manual?ZERO:amount);
   payload.put("postingCounterpartAmount",manual?amount:ZERO);
  }
  if(amount!=null&&amount.signum()==0&&(!Boolean.TRUE.equals(payload.get("payableRecognition"))||payload.get("apAmount") instanceof BigDecimal ap&&ap.signum()==0))payload.put("accountingImpact","SOURCE_CONFIRMATION");
 }
