 private static List<BigDecimal> split(BigDecimal amount,List<BigDecimal>weights,List<Long>ids,int decimals){if(amount.signum()<0)return split(amount.negate(),weights,ids,decimals).stream().map(BigDecimal::negate).toList();BigDecimal total=weights.stream().reduce(ZERO,BigDecimal::add);if(total.signum()<=0)throw Inputs.bad("分摊依据合计必须大于零");List<BigDecimal>out=new ArrayList<>();BigDecimal allocated=ZERO;int largest=0;for(int x=0;x<weights.size();x++){BigDecimal v=amount.multiply(weights.get(x)).divide(total,decimals,RoundingMode.HALF_UP);out.add(v);allocated=allocated.add(v);if(weights.get(x).compareTo(weights.get(largest))>0||weights.get(x).compareTo(weights.get(largest))==0&&ids.get(x)<ids.get(largest))largest=x;}BigDecimal difference=amount.subtract(allocated);if(out.get(largest).add(difference).signum()>=0)out.set(largest,out.get(largest).add(difference));else {List<Integer>order=new ArrayList<>();for(int x=0;x<weights.size();x++)order.add(x);order.sort(Comparator.<Integer,BigDecimal>comparing(weights::get).reversed().thenComparing(ids::get));for(int x:order){BigDecimal absorb=out.get(x).min(difference.negate());out.set(x,out.get(x).subtract(absorb));difference=difference.add(absorb);if(difference.signum()==0)break;}if(difference.signum()!=0)throw Inputs.bad("费用小于可分摊的币种精度");}return out;}
