  j.update("INSERT INTO cst_valuation_change(country_id,book_id,batch_id,adjustment_id,qty_basis,amount,inventory_amount,sold_amount,unit_delta,source_type,source_id,seq,biz_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",a.requireCountry(),book,batch,adjustment,quantity,delta,inventory,sold,unit,source,sourceId,source.equals("FEE_ALLOCATION")&&delta.signum()<0?2:1,date,a.userId());
  for(var child:j.queryForList("SELECT i.id,i.batch_id,i.qty,c.id return_cogs FROM cst_inbound_cost i JOIN cst_cogs c ON c.country_id=i.country_id AND c.source_type=i.source_type AND c.source_line_id=i.source_line_id WHERE i.country_id=? AND i.book_id=? AND i.original_cogs_id IS NOT NULL AND i.batch_id<>? ORDER BY i.id",a.requireCountry(),book,batch)){BigDecimal inherited=shares.cogs.getOrDefault(((Number)child.get("return_cogs")).longValue(),ZERO).negate();if(inherited.signum()==0)continue;inbound(a,((Number)child.get("id")).longValue(),false);int childSeq=10+j.queryForObject("SELECT count(*) FROM cst_valuation_change WHERE country_id=? AND source_type=? AND source_id=? AND batch_id=?",Integer.class,a.requireCountry(),source,sourceId,child.get("batch_id"));j.update("INSERT INTO cst_valuation_change(country_id,book_id,batch_id,adjustment_id,qty_basis,amount,inventory_amount,sold_amount,unit_delta,source_type,source_id,seq,biz_date,created_by) VALUES(?,?,?,?,?,0,0,0,?,?,?,?,?,?)",a.requireCountry(),book,child.get("batch_id"),adjustment,child.get("qty"),inherited.divide((BigDecimal)child.get("qty"),12,RoundingMode.HALF_UP),source,sourceId,childSeq,date,a.userId());}
