 private List<Map<String,Object>> feeChanges(Access a,long book,LocalDate asOf){return j.queryForList("SELECT v.batch_id,v.unit_delta*v.qty_basis amount,v.created_at FROM cst_valuation_change v JOIN cst_inbound_cost i ON i.country_id=v.country_id AND i.batch_id=v.batch_id WHERE v.country_id=? AND v.book_id=? AND v.source_type='FEE_ALLOCATION' AND i.original_cogs_id IS NULL AND v.biz_date<=? ORDER BY v.id",a.requireCountry(),book,asOf);}
 private BigDecimal transferDifference(Access a,long book,long transfer,long batch,BigDecimal qty,LocalDate date){BigDecimal result=ZERO;var source=j.queryForMap("SELECT p.qty,m.created_at FROM cst_transfer_cost_part p JOIN cst_valuation_movement m ON m.country_id=p.country_id AND m.transfer_cost_id=p.transfer_cost_id AND m.action='TRANSFER_OUT' WHERE p.country_id=? AND p.transfer_cost_id=? AND p.batch_id=?",a.requireCountry(),transfer,batch);var disposed=j.queryForMap("SELECT (SELECT coalesce(sum(qty_change),0) FROM cst_valuation_movement WHERE country_id=? AND transfer_cost_id=? AND batch_id=? AND action='TRANSFER_IN')+(SELECT coalesce(sum(qty),0) FROM cst_transfer_loss WHERE country_id=? AND transfer_cost_id=? AND batch_id=?) qty",a.requireCountry(),transfer,batch,a.requireCountry(),transfer,batch);BigDecimal cumulative=(BigDecimal)disposed.get("qty"),previous=cumulative.subtract(qty);for(var change:feeChanges(a,book,date)){if(!((java.sql.Timestamp)change.get("created_at")).after((java.sql.Timestamp)source.get("created_at")))continue;var shares=contribution(a,book,((Number)change.get("batch_id")).longValue(),(BigDecimal)change.get("amount"));BigDecimal total=shares.originalTransfers.getOrDefault(transfer,Map.of()).getOrDefault(batch,ZERO);result=result.add(ratio(total,cumulative,(BigDecimal)source.get("qty")).subtract(ratio(total,previous,(BigDecimal)source.get("qty"))));}return result;}
 @Override public BigDecimal receiveDifference(RequestContext c,long book,long wh,long product,long transfer,long batch,BigDecimal qty,LocalDate date){var a=auth.authorize(c);BigDecimal delta=transferDifference(a,book,transfer,batch,qty,date);if(delta.signum()==0)return ZERO;gate(a,book,date);var before=lockPool(a,book,wh,product);if(before.get("amount")==null)throw new ApiException(409,"CST_COST_MISSING","请先恢复原调出成本");var current=j.queryForMap("SELECT amount FROM cst_batch_value WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? AND batch_id=? FOR UPDATE",a.requireCountry(),book,wh,product,batch);if(current.get("amount")==null||((BigDecimal)current.get("amount")).add(delta).signum()<0)throw new ApiException(409,"CST_COST_MISSING","调入批次成本尚未完整");long movement=j.queryForObject("SELECT max(id) FROM cst_valuation_movement WHERE country_id=? AND transfer_cost_id=? AND batch_id=? AND action='TRANSFER_IN'",Long.class,a.requireCountry(),transfer,batch);long adjustment=transferAdjustment(a,book,wh,product,batch,movement,qty,ZERO,ZERO,date,"调拨在途后到费用随货转入");j.update("UPDATE cst_batch_value SET amount=amount+? WHERE country_id=? AND book_id=? AND warehouse_id=? AND product_id=? AND batch_id=?",delta,a.requireCountry(),book,wh,product,batch);movement(a,book,wh,product,batch,"CST_ADJUSTMENT",adjustment,"ADJUSTMENT",1,ZERO,delta,before,date);events.publish(a.requireCountry(),book,"CST_COST_ADJUSTED","CST_ADJUSTMENT",adjustment,1,date,Map.of("amount",ZERO,"inventoryAmount",ZERO,"soldAmount",ZERO,"productId",product,"batchId",batch));return delta;}
 @Override public void lossDifference(RequestContext c,long book,long transfer,long cogs,long batch,BigDecimal qty,LocalDate date){var a=auth.authorize(c);BigDecimal delta=transferDifference(a,book,transfer,batch,qty,date);if(delta.signum()==0)return;var loss=row(a,"cst_cogs",cogs,false);long adjustment=transferAdjustment(a,book,n(loss,"warehouseId"),n(loss,"productId"),batch,cogs,qty,ZERO,delta,date,"调拨报损结转后到费用");events.publish(a.requireCountry(),book,"CST_COST_ADJUSTED","CST_ADJUSTMENT",adjustment,1,date,Map.of("amount",delta,"inventoryAmount",ZERO,"soldAmount",delta,"productId",loss.get("productId"),"batchId",batch));}
 private long transferAdjustment(Access a,long book,long wh,long product,long batch,long source,BigDecimal qty,BigDecimal inventory,BigDecimal sold,LocalDate date,String reason){BigDecimal amount=inventory.add(sold);long id=j.queryForObject("INSERT INTO cst_cost_adjustment(country_id,book_id,doc_no,batch_id,warehouse_id,product_id,target,amount,inventory_amount,sold_amount,reason,source_type,source_id,biz_date,status,confirmed_by,confirmed_at,created_by) VALUES(?,?,?,?,?,?,'MIXED',?,?,?,?,'TRANSFER_COST',?,?,'CONFIRMED',?,clock_timestamp(),?) RETURNING id",Long.class,a.requireCountry(),book,numbers.next(a,"CST_ADJUSTMENT",date),batch,wh,product,amount,inventory,sold,reason,source,date,a.userId(),a.userId());j.update("INSERT INTO cst_valuation_change(country_id,book_id,batch_id,adjustment_id,qty_basis,amount,inventory_amount,sold_amount,unit_delta,source_type,source_id,biz_date,created_by) VALUES(?,?,?,?,?,?,?,?,0,'TRANSFER_COST',?,?,?)",a.requireCountry(),book,batch,id,qty,amount,inventory,sold,source,date,a.userId());return id;}
 private void transitBalances(Access a,long book,LocalDate asOf,List<Map<String,Object>>out){
  for(var raw:j.queryForList("SELECT t.*,m.created_at out_created_at,coalesce(t.amount,x.amount) effective_amount FROM cst_transfer_cost t JOIN cst_valuation_movement m ON m.country_id=t.country_id AND m.transfer_cost_id=t.id AND m.action='TRANSFER_OUT' LEFT JOIN cst_transfer_completion x ON x.country_id=t.country_id AND x.transfer_cost_id=t.id AND x.biz_date<=? WHERE t.country_id=? AND t.book_id=? AND t.biz_date<=? ORDER BY t.id",asOf,a.requireCountry(),book,asOf)){
   var r=DbRows.camel(raw);if(!a.canRow(r))continue;long id=n(r,"id");
   var received=j.queryForMap("SELECT coalesce(sum(m.qty_change),0) qty,coalesce(sum(coalesce(m.amount_change,x.amount_change)),0) amount,bool_or(coalesce(m.amount_change,x.amount_change) IS NULL) missing FROM cst_valuation_movement m LEFT JOIN cst_movement_completion x ON x.country_id=m.country_id AND x.movement_id=m.id AND x.biz_date<=? WHERE m.country_id=? AND m.transfer_cost_id=? AND m.action='TRANSFER_IN' AND m.biz_date<=?",asOf,a.requireCountry(),id,asOf);
   var loss=j.queryForMap("SELECT coalesce(sum(l.qty),0) qty,coalesce(sum(coalesce(l.amount,x.amount)),0) amount,bool_or(coalesce(l.amount,x.amount) IS NULL) missing FROM cst_transfer_loss l JOIN cst_cogs c ON c.country_id=l.country_id AND c.id=l.cogs_id LEFT JOIN cst_transfer_loss_completion x ON x.country_id=l.country_id AND x.loss_id=l.id AND x.biz_date<=? WHERE l.country_id=? AND l.transfer_cost_id=? AND c.biz_date<=?",asOf,a.requireCountry(),id,asOf);
   BigDecimal qty=d(r,"qty").subtract((BigDecimal)received.get("qty")).subtract((BigDecimal)loss.get("qty"));if(qty.signum()==0)continue;
   BigDecimal amount=raw.get("effective_amount")==null||Boolean.TRUE.equals(received.get("missing"))||Boolean.TRUE.equals(loss.get("missing"))?null:((BigDecimal)raw.get("effective_amount")).subtract((BigDecimal)received.get("amount")).subtract((BigDecimal)loss.get("amount"));
   if(amount!=null)for(var change:feeChanges(a,book,asOf)){if(!((java.sql.Timestamp)change.get("created_at")).after((java.sql.Timestamp)raw.get("out_created_at")))continue;amount=amount.add(contribution(a,book,((Number)change.get("batch_id")).longValue(),(BigDecimal)change.get("amount"),asOf).transit.getOrDefault(id,Map.of()).values().stream().reduce(ZERO,BigDecimal::add));}
   Map<String,Object>value=new LinkedHashMap<>();value.put("sourceType","CST_TRANSFER_COST");value.put("sourceId",id);value.put("warehouseId",r.get("warehouseId"));value.put("productId",r.get("productId"));value.put("qty",qty);value.put("amount",amount);value.put("costMissing",amount==null);value.put("inTransit",true);out.add(value);
  }
 }

 private void completeTransfer(Access a,long book,long transfer,BigDecimal amount,Map<Long,BigDecimal>parts,LocalDate date){j.update("INSERT INTO cst_transfer_completion(country_id,book_id,transfer_cost_id,amount,biz_date,completed_by) VALUES(?,?,?,?,?,?) ON CONFLICT DO NOTHING",a.requireCountry(),book,transfer,amount,date,a.userId());for(var part:parts.entrySet())if(part.getValue()!=null)j.update("INSERT INTO cst_transfer_part_completion(country_id,book_id,transfer_cost_id,batch_id,amount,biz_date,completed_by) VALUES(?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",a.requireCountry(),book,transfer,part.getKey(),part.getValue(),date,a.userId());}
 private void completePendingLosses(Access a,long book,LocalDate date){for(var l:j.queryForList("SELECT l.*,coalesce(p.amount,x.amount) original_amount,p.qty original_qty FROM cst_transfer_loss l JOIN cst_cogs c ON c.country_id=l.country_id AND c.id=l.cogs_id JOIN cst_transfer_cost_part p ON p.country_id=l.country_id AND p.transfer_cost_id=l.transfer_cost_id AND p.batch_id=l.batch_id LEFT JOIN cst_transfer_part_completion x ON x.country_id=p.country_id AND x.transfer_cost_id=p.transfer_cost_id AND x.batch_id=p.batch_id WHERE l.country_id=? AND c.book_id=? AND l.amount IS NULL ORDER BY l.cogs_id,l.id",a.requireCountry(),book)){if(l.get("original_amount")==null)continue;var before=j.queryForMap("SELECT (SELECT coalesce(sum(m.qty_change),0) FROM cst_valuation_movement m WHERE m.country_id=? AND m.transfer_cost_id=? AND m.batch_id=? AND m.action='TRANSFER_IN' AND m.id<?)+(SELECT coalesce(sum(p.qty),0) FROM cst_transfer_loss p WHERE p.country_id=? AND p.transfer_cost_id=? AND p.batch_id=? AND p.cogs_id<?) qty,(SELECT coalesce(sum(coalesce(m.amount_change,x.amount_change)),0) FROM cst_valuation_movement m LEFT JOIN cst_movement_completion x ON x.country_id=m.country_id AND x.movement_id=m.id WHERE m.country_id=? AND m.transfer_cost_id=? AND m.batch_id=? AND m.action='TRANSFER_IN' AND m.id<?)+(SELECT coalesce(sum(coalesce(p.amount,x.amount)),0) FROM cst_transfer_loss p LEFT JOIN cst_transfer_loss_completion x ON x.country_id=p.country_id AND x.loss_id=p.id WHERE p.country_id=? AND p.transfer_cost_id=? AND p.batch_id=? AND p.cogs_id<?) amount",a.requireCountry(),l.get("transfer_cost_id"),l.get("batch_id"),l.get("cogs_id"),a.requireCountry(),l.get("transfer_cost_id"),l.get("batch_id"),l.get("cogs_id"),a.requireCountry(),l.get("transfer_cost_id"),l.get("batch_id"),l.get("cogs_id"),a.requireCountry(),l.get("transfer_cost_id"),l.get("batch_id"),l.get("cogs_id"));BigDecimal amount=ratio((BigDecimal)l.get("original_amount"),((BigDecimal)before.get("qty")).add((BigDecimal)l.get("qty")),(BigDecimal)l.get("original_qty")).subtract((BigDecimal)before.get("amount"));j.update("INSERT INTO cst_transfer_loss_completion(country_id,book_id,loss_id,amount,biz_date,completed_by) VALUES(?,?,?,?,?,?) ON CONFLICT DO NOTHING",a.requireCountry(),book,l.get("id"),amount,date,a.userId());}
  for(var c:j.queryForList("SELECT c.id,c.qty,sum(coalesce(l.amount,x.amount)) amount,bool_and(coalesce(l.amount,x.amount) IS NOT NULL) complete FROM cst_cogs c JOIN cst_transfer_loss l ON l.country_id=c.country_id AND l.cogs_id=c.id LEFT JOIN cst_transfer_loss_completion x ON x.country_id=l.country_id AND x.loss_id=l.id WHERE c.country_id=? AND c.book_id=? AND c.amount IS NULL GROUP BY c.id",a.requireCountry(),book))if(Boolean.TRUE.equals(c.get("complete")))completeCogs(a,book,((Number)c.get("id")).longValue(),(BigDecimal)c.get("amount"),(BigDecimal)c.get("qty"),date);
 }
